import React, { useState } from 'react';
import { Sparkles, Loader2, Image as ImageIcon } from 'lucide-react';
import { generateDesignConcept } from '../services/geminiService';
import { LoadingState } from '../types';

export const Visualizer: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [status, setStatus] = useState<LoadingState>(LoadingState.IDLE);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!prompt.trim()) return;

    setStatus(LoadingState.LOADING);
    try {
      const imageUrl = await generateDesignConcept(prompt);
      setGeneratedImage(imageUrl);
      setStatus(LoadingState.SUCCESS);
    } catch (error) {
      console.error(error);
      setStatus(LoadingState.ERROR);
    }
  };

  return (
    <section id="ai-design" className="py-24 bg-brand-dark text-white relative overflow-hidden">
      {/* Decorative elements */}
      <div className="absolute top-0 right-0 w-1/3 h-full bg-brand-gold/5 blur-[100px] pointer-events-none"></div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
        <div className="grid lg:grid-cols-2 gap-16 items-center">

          <div className="fade-in-section">
            <div className="flex items-center gap-2 mb-4 text-brand-gold">
              <Sparkles className="w-5 h-5" />
              <span className="font-bold tracking-widest uppercase">AI Design Studio</span>
            </div>
            <h2 className="font-serif text-4xl md:text-5xl font-bold mb-6">
              Visualize Your Dream <br />
              <span className="text-brand-gold">Before We Build It</span>
            </h2>
            <p className="text-gray-300 text-lg mb-8 leading-relaxed">
              Not sure how a retaining wall would look with a new patio? Use our advanced AI tool to generate a concept image of your project. Describe your vision, and let us show you the possibilities.
            </p>

            <form onSubmit={handleGenerate} className="space-y-4">
              <div>
                <label htmlFor="prompt" className="block text-sm font-medium text-gray-300 mb-2">
                  Describe your ideal backyard (e.g., "A modern stone fire pit with curved seating and travertine pavers")
                </label>
                <textarea
                  id="prompt"
                  rows={4}
                  className="w-full bg-white/5 border border-white/10 rounded-lg p-4 text-white placeholder-gray-500 focus:ring-2 focus:ring-brand-gold focus:border-transparent transition-all outline-none resize-none"
                  placeholder="I want a rustic outdoor kitchen with a pergola..."
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                />
              </div>
              <button
                type="submit"
                disabled={status === LoadingState.LOADING || !prompt}
                className="group flex items-center justify-center gap-3 w-full sm:w-auto px-8 py-4 bg-gradient-to-r from-brand-gold to-yellow-600 hover:from-brand-goldHover hover:to-yellow-700 text-white font-bold rounded-lg transition-all shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {status === LoadingState.LOADING ? (
                  <>
                    <Loader2 className="w-5 h-5 animate-spin" />
                    Generating Vision...
                  </>
                ) : (
                  <>
                    <Sparkles className="w-5 h-5 group-hover:rotate-12 transition-transform" />
                    Generate Design
                  </>
                )}
              </button>
            </form>

            {status === LoadingState.ERROR && (
               <p className="mt-4 text-red-400 text-sm">Oops! Something went wrong. Please check your connection or try a different description. (API Key required)</p>
            )}
          </div>

          <div className="relative fade-in-section delay-200">
             <div className="aspect-video w-full bg-white/5 rounded-2xl border border-white/10 overflow-hidden flex items-center justify-center relative group">
                {generatedImage ? (
                  <img 
                    src={generatedImage} 
                    alt="AI Generated Design" 
                    className="w-full h-full object-cover animate-in fade-in zoom-in duration-700"
                  />
                ) : (
                  <div className="text-center p-8">
                     <div className="w-20 h-20 bg-white/5 rounded-full flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                        <ImageIcon className="w-8 h-8 text-white/30" />
                     </div>
                     <p className="text-white/50 text-lg">Your design will appear here</p>
                  </div>
                )}

                {/* Overlay for generated image */}
                {generatedImage && (
                  <div className="absolute bottom-0 left-0 right-0 p-4 bg-gradient-to-t from-black/80 to-transparent">
                    <p className="text-white text-xs font-mono">AI Generated Concept • AGS Stones</p>
                  </div>
                )}
             </div>

             {/* Decorative Frame */}
             <div className="absolute -inset-4 border-2 border-brand-gold/20 rounded-3xl -z-10 transform rotate-2"></div>
          </div>

        </div>
      </div>
    </section>
  );
};

