import React, { useState, useRef, useEffect } from 'react';
import { MoveHorizontal } from 'lucide-react';

export const BeforeAfter: React.FC = () => {
  const [sliderPosition, setSliderPosition] = useState(50);
  const containerRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);

  const handleMove = (clientX: number) => {
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect();
      const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
      const percentage = (x / rect.width) * 100;
      setSliderPosition(percentage);
    }
  };

  const handleMouseDown = () => { isDragging.current = true; };
  const handleMouseUp = () => { isDragging.current = false; };
  const handleMouseMove = (e: React.MouseEvent) => { if (isDragging.current) handleMove(e.clientX); };

  // Touch support
  const handleTouchMove = (e: React.TouchEvent) => { handleMove(e.touches[0].clientX); };

  // Global mouse up to catch drags outside component
  useEffect(() => {
    const handleGlobalMouseUp = () => { isDragging.current = false; };
    window.addEventListener('mouseup', handleGlobalMouseUp);
    return () => window.removeEventListener('mouseup', handleGlobalMouseUp);
  }, []);

  return (
    <section id="portfolio" className="py-24 bg-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-16 fade-in-section">
          <h2 className="font-serif text-4xl font-bold text-brand-dark mb-4">Transformation Gallery</h2>
          <p className="text-gray-600">Drag the slider to see the AGS difference.</p>
        </div>

        <div className="relative max-w-5xl mx-auto h-[400px] md:h-[600px] rounded-2xl overflow-hidden shadow-2xl select-none fade-in-section">
          <div 
            ref={containerRef}
            className="relative w-full h-full cursor-ew-resize"
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onTouchMove={handleTouchMove}
          >
            {/* Image 2 (After) - Background */}
            <div className="absolute inset-0">
               <img 
                 src="https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?q=80&w=2653&auto=format&fit=crop" 
                 alt="After - Beautiful Patio" 
                 className="w-full h-full object-cover"
                 draggable={false}
               />
               <div className="absolute top-4 right-4 bg-white/90 px-3 py-1 rounded text-xs font-bold uppercase tracking-widest text-brand-dark">After</div>
            </div>

            {/* Image 1 (Before) - Clipped on top */}
            <div 
              className="absolute inset-0 overflow-hidden"
              style={{ width: `${sliderPosition}%` }}
            >
              <img 
                src="https://images.unsplash.com/photo-1594489242636-c4d67362ce5a?q=80&w=2670&auto=format&fit=crop" 
                alt="Before - Empty Yard" 
                className="w-full h-full object-cover max-w-none"
                style={{ width: containerRef.current?.offsetWidth || '100%' }} // Keep aspect ratio consistent
                draggable={false}
              />
              <div className="absolute top-4 left-4 bg-brand-dark/90 text-white px-3 py-1 rounded text-xs font-bold uppercase tracking-widest">Before</div>
            </div>

            {/* Slider Handle */}
            <div 
              className="absolute top-0 bottom-0 w-1 bg-white cursor-ew-resize z-20"
              style={{ left: `${sliderPosition}%` }}
            >
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full shadow-lg flex items-center justify-center text-brand-gold">
                <MoveHorizontal size={20} />
