          <div className="md:col-span-2 relative h-[500px] rounded-3xl overflow-hidden shadow-2xl select-none fade-in-section group">
            <div 
              ref={containerRef}
              className="relative w-full h-full cursor-ew-resize"
              onMouseDown={handleMouseDown}
              onMouseMove={handleMouseMove}
              onTouchMove={handleTouchMove}
            >
              {/* After Image */}
              <div className="absolute inset-0">
                 <img 
                   src="https://images.unsplash.com/photo-1595846519845-68e298c2edd8?q=80&w=2670&auto=format&fit=crop" 
