import React, { useState, useEffect } from 'react';
import { Home, Grid, Phone, MessageSquare } from 'lucide-react';

export const MobileNav: React.FC = () => {
  const [activeSection, setActiveSection] = useState('home');
  const [isScrollingDown, setIsScrollingDown] = useState(false);
  const [lastScrollY, setLastScrollY] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      const currentScrollY = window.scrollY;

      // Determine scroll direction for button animation
      setIsScrollingDown(currentScrollY > lastScrollY && currentScrollY > 100);
      setLastScrollY(currentScrollY);

      // Determine active section
      const sections = ['home', 'services', 'contact'];
      for (const sectionId of sections) {
        const element = document.getElementById(sectionId);
        if (element) {
          const rect = element.getBoundingClientRect();
          // If top of section is within the top half of the screen
          if (rect.top <= window.innerHeight / 2 && rect.bottom >= 100) {
            setActiveSection(sectionId);
          }
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [lastScrollY]);

  const scrollTo = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <div className="fixed bottom-0 left-0 w-full bg-white/95 backdrop-blur-xl border-t border-gray-200 z-50 md:hidden pb-safe shadow-[0_-5px_20px_rgba(0,0,0,0.05)] transition-transform duration-300">
      <div className="grid grid-cols-4 h-16 items-center px-2">

        {/* Home */}
        <button 
          onClick={() => scrollTo('home')}
          className={`flex flex-col items-center justify-center h-full w-full transition-colors duration-300 ${
            activeSection === 'home' ? 'text-brand-dark' : 'text-gray-400 hover:text-gray-600'
          }`}
        >
          <Home size={22} strokeWidth={activeSection === 'home' ? 2.5 : 2} className={`transition-transform duration-300 ${activeSection === 'home' ? 'scale-110 mb-1' : ''}`} />
          <span className={`text-[10px] font-medium transition-all duration-300 ${activeSection === 'home' ? 'opacity-100 font-bold' : 'opacity-0 h-0 overflow-hidden'}`}>
            Home
          </span>
          {activeSection === 'home' && <div className="h-1 w-1 bg-brand-gold rounded-full mt-1 animate-pulse"></div>}
        </button>

