            <span className={`text-[9px] font-bold mt-1 transition-colors duration-300 ${activeSection === 'home' ? 'text-brand-dark' : 'text-gray-400'}`}>
              Home
            </span>
          </button>

          {/* Services */}
          <button 
            onClick={() => scrollTo('services')}
            className={`group flex flex-col items-center justify-center h-full w-full relative`}
          >
            <div className={`p-1 rounded-xl transition-all duration-300 ${activeSection === 'services' ? 'bg-brand-light' : ''}`}>
               <Grid size={22} className={`transition-all duration-300 ${activeSection === 'services' ? 'text-brand-dark fill-brand-dark/20' : 'text-gray-400'}`} />
