              className={`rounded-full shadow-2xl border-4 border-slate-50 bg-gradient-to-br from-brand-gold to-brand-goldHover text-white flex items-center justify-center transition-all duration-500 ease-out ${
                isScrollingDown ? 'w-12 h-12 translate-y-2' : 'w-14 h-14 translate-y-0'
              }`}
            >
