export const InteractiveProcess: React.FC = () => {
  const [activeStep, setActiveStep] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;

      const stepElements = document.querySelectorAll('.process-step');

      stepElements.forEach((el, index) => {
        const rect = el.getBoundingClientRect();
        // If the element is near the center of the viewport
        if (rect.top >= 0 && rect.top <= window.innerHeight / 2) {
          setActiveStep(index);
        }
      });
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <section id="process" className="bg-white py-24 relative">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-16 fade-in-section">
           <span className="text-brand-gold font-bold tracking-[0.2em] uppercase text-sm">How We Work</span>
           <h2 className="mt-2 font-serif text-4xl md:text-5xl font-bold text-brand-dark">The AGS Process</h2>
        </div>

        <div className="flex flex-col lg:flex-row gap-12" ref={containerRef}>

          {/* Left Side: Scrolling Content */}
          <div className="lg:w-1/2 flex flex-col gap-24 py-12">
            {steps.map((step, index) => (
              <div 
                key={step.id} 
                className={`process-step transition-opacity duration-500 ${index === activeStep ? 'opacity-100' : 'opacity-30'}`}
              >
                 <div className="flex items-center gap-4 mb-4">
                    <div className={`w-12 h-12 rounded-full flex items-center justify-center font-bold text-xl border-2 transition-colors duration-500 ${index === activeStep ? 'bg-brand-gold border-brand-gold text-white' : 'bg-transparent border-gray-300 text-gray-300'}`}>
                       {step.id}
                    </div>
                    <div className={`p-2 rounded-full ${index === activeStep ? 'bg-brand-light text-brand-dark' : 'text-gray-300'}`}>
                      {step.icon}
                    </div>
                 </div>
                 <h3 className="text-3xl font-serif font-bold text-brand-dark mb-4">{step.title}</h3>
                 <p className="text-lg text-gray-600 leading-relaxed max-w-md">{step.description}</p>
              </div>
            ))}
          </div>

          {/* Right Side: Sticky Image Display */}
          <div className="hidden lg:block lg:w-1/2 relative">
             <div className="sticky top-32 h-[500px] w-full rounded-3xl overflow-hidden shadow-2xl border-4 border-white ring-1 ring-gray-100">
                {steps.map((step, index) => (
                  <div 
                    key={step.id}
                    className={`absolute inset-0 transition-opacity duration-700 ease-in-out ${index === activeStep ? 'opacity-100 z-10' : 'opacity-0 z-0'}`}
                  >
                     <img src={step.image} alt={step.title} className="w-full h-full object-cover" />
                     <div className="absolute inset-0 bg-gradient-to-t from-brand-dark/60 via-transparent to-transparent"></div>
                     <div className="absolute bottom-8 left-8 text-white">
                        <p className="uppercase tracking-widest text-xs font-bold mb-2 text-brand-gold">Step 0{step.id}</p>
                        <h4 className="font-serif text-2xl font-bold">{step.title}</h4>
                     </div>
                  </div>
                ))}
             </div>
          </div>
        </div>

        {/* Mobile Only Image (Static Last Image) */}
        <div className="lg:hidden mt-8 rounded-2xl overflow-hidden h-64 shadow-lg">
           <img src={steps[activeStep].image} alt="Process" className="w-full h-full object-cover" />
        </div>

      </div>
    </section>
  );
};

import React, { useState, useEffect } from 'react';
