import { FloatingWidget } from './components/FloatingWidget';
import { MobileNav } from './components/MobileNav';

const App: React.FC = () => {
  useEffect(() => {
    // Intersection Observer for scroll animations
    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
        }
      });
    }, {
      threshold: 0.1, // Trigger when 10% visible
      rootMargin: "0px 0px -50px 0px"
    });

    const hiddenElements = document.querySelectorAll('.fade-in-section');
    hiddenElements.forEach((el) => observer.observe(el));

    return () => observer.disconnect();
  }, []);

  return (
    <div className="font-sans antialiased text-brand-dark bg-slate-50 pb-24 md:pb-0">
      <Header />
      <main>
        <Hero />
        <Services />
        <WhyChooseUs />
        <BeforeAfter />
        <DayNightSlider /> {/* Added here to sell the "Ambience" */}
        <InteractiveProcess />
        <Testimonials />
        <FAQ /> {/* Added FAQ section for SEO */}
        <Contact />
      </main>
      <Footer />
      {/* Floating Widget hidden on mobile to prevent overlap with nav */}
      <div className="hidden md:block">
        <FloatingWidget />
      </div>
      <MobileNav />
    </div>
  );
};

export default App;

