import React, { useState, useEffect } from 'react';
import { Phone, X, MessageSquare } from 'lucide-react';

export const FloatingWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    // Trigger entrance animation
    setIsVisible(true);

    // Auto-open popup after 5 seconds
    const timer = setTimeout(() => {
      setIsOpen(true);
    }, 5000);

    return () => clearTimeout(timer);
  }, []);

  const toggleOpen = () => setIsOpen(!isOpen);

  // Animation classes for entrance
  const entranceClass = isVisible 
    ? "opacity-100 translate-y-0 scale-100" 
    : "opacity-0 translate-y-10 scale-90";

  return (
    // Mobile: bottom-24 to sit above the mobile nav. Desktop: bottom-6.
    <div className={`fixed bottom-24 right-4 md:bottom-6 md:right-6 z-[60] flex flex-col items-end transition-all duration-700 ease-out ${entranceClass}`}>

       {/* Popup Bubble */}
       {isOpen && (
         <div className="bg-white p-5 rounded-lg shadow-2xl mb-4 max-w-xs relative border-l-4 border-brand-gold animate-[fade-up_0.4s_ease-out] origin-bottom-right mx-2 md:mx-0">
            <button 
              onClick={() => setIsOpen(false)}
              className="absolute top-2 right-2 text-gray-400 hover:text-gray-600"
            >
               <X size={16} />
            </button>
            <h4 className="font-bold text-gray-900 mb-1">Questions?</h4>
            <p className="text-sm text-gray-600 mb-3">Speak with our paver experts instantly.</p>
            <a 
              href="tel:6784287630" 
              className="flex items-center justify-center gap-2 bg-brand-gold hover:bg-brand-goldHover text-white py-2 px-4 rounded font-bold text-sm w-full transition-colors"
            >
               <Phone size={16} />
               Click to Call Now
            </a>
         </div>
       )}

       {/* Floating Action Button */}
       <button 
           onClick={toggleOpen}
           className={`bg-brand-gold text-white p-4 rounded-full shadow-2xl hover:scale-110 transition-transform ${isOpen ? 'rotate-0' : 'animate-bounce'}`}
           aria-label="Chat with us"
        >
           {isOpen ? <X size={24} /> : <MessageSquare size={24} />}
        </button>
    </div>
  );
};

