import React, { useState, useEffect } from 'react';
import { Home, Layers, Phone, Mail } from 'lucide-react';

export const MobileNav: React.FC = () => {
  const [activeSection, setActiveSection] = useState('home');

  useEffect(() => {
    const handleScroll = () => {
      const sections = ['home', 'services', 'contact'];
      for (const sectionId of sections) {
        const element = document.getElementById(sectionId);
        if (element) {
          const rect = element.getBoundingClientRect();
          if (rect.top <= window.innerHeight / 2 && rect.bottom >= 100) {
            setActiveSection(sectionId);
          }
        }
      }
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollTo = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <div className="fixed bottom-6 inset-x-4 z-50 md:hidden flex justify-center pb-safe">
      {/* Premium Floating Island Container */}
      <div className="bg-[#1a1a1a]/95 backdrop-blur-md text-white rounded-full px-5 py-3 shadow-[0_8px_30px_rgba(0,0,0,0.4)] border border-white/10 flex items-center justify-between gap-6 w-full max-w-sm">

        {/* Home */}
        <button 
          onClick={() => scrollTo('home')}
          className={`flex flex-col items-center justify-center w-10 relative transition-colors ${activeSection === 'home' ? 'text-brand-gold' : 'text-gray-400'}`}
        >
          <Home size={20} strokeWidth={activeSection === 'home' ? 2.5 : 2} />
          <span className="text-[9px] mt-1 font-medium">Home</span>
        </button>

        {/* Services */}
        <button 
          onClick={() => scrollTo('services')}
          className={`flex flex-col items-center justify-center w-10 relative transition-colors ${activeSection === 'services' ? 'text-brand-gold' : 'text-gray-400'}`}
        >
          <Layers size={20} strokeWidth={activeSection === 'services' ? 2.5 : 2} />
          <span className="text-[9px] mt-1 font-medium">Work</span>
        </button>

        {/* CALL (Integrated Button with Online Indicator) */}
        <a 
          href="tel:6784287630" 
          className="relative bg-brand-gold text-white pl-4 pr-5 py-2.5 rounded-full font-bold text-xs uppercase tracking-wider hover:bg-white hover:text-brand-gold transition-all shadow-lg flex items-center gap-2 -mt-6 mb-2 border-4 border-slate-50 scale-110"
        >
           {/* Online Dot */}
           <span className="absolute top-1 right-1 flex h-3 w-3">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
              <span className="relative inline-flex rounded-full h-3 w-3 bg-green-500 border-2 border-brand-gold"></span>
           </span>

           <Phone size={16} fill="currentColor" /> 
           <div className="flex flex-col leading-none">
             <span>Call Us</span>
             <span className="text-[8px] opacity-90 normal-case font-normal mt-0.5">We're Online</span>
           </div>
