import React, { useEffect, useRef, useState } from 'react';

export const ZParallaxShowcase: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;

      const rect = containerRef.current.getBoundingClientRect();
      const height = rect.height - window.innerHeight;
      const top = -rect.top;

      // Calculate progress 0 to 1 based on scroll within the container
      const progress = Math.max(0, Math.min(1, top / height));

      // Use requestAnimationFrame for smooth performance
      requestAnimationFrame(() => setScrollProgress(progress));
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    // A tall container to allow for scroll distance (300vh = 3 screens worth of scrolling)
    <section ref={containerRef} className="relative h-[300vh] bg-black">

      {/* Sticky Viewport - This stays fixed while we scroll inside the parent */}
      <div className="sticky top-0 h-screen w-full overflow-hidden flex items-center justify-center perspective-[100px]">

        {/* Layer 3: The Background (The Destination) */}
        <div 
           className="absolute inset-0 w-full h-full"
           style={{
             opacity: Math.min(1, scrollProgress * 2), // Fades in as we enter
             transform: `scale(${1 + (1 - scrollProgress) * 0.5})`, // Gently scales down as we approach
             zIndex: 10
           }}
        >
           <img 
             src="https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?q=80&w=2600&auto=format&fit=crop" 
             alt="Luxury Destination" 
             className="w-full h-full object-cover brightness-75"
           />
           <div className="absolute inset-0 bg-black/30"></div>
        </div>

        {/* Layer 2: The "Doorway" / Frame (Walkthrough Effect) */}
        <div 
          className="absolute inset-0 flex items-center justify-center pointer-events-none"
          style={{
             // This logic creates the "Zoom In" effect. 
             // As scrollProgress goes 0 -> 1, Scale goes 1 -> 40 (massive zoom past camera)
             transform: `scale(${1 + scrollProgress * 30})`,
             opacity: 1 - Math.pow(scrollProgress, 5), // Fades out sharply at the very end
             zIndex: 20
          }}
        >
           {/* We use a mask or a transparent PNG frame concept here. 
               Using a clip-path to simulate a window/archway we fly through. */}
           <div className="w-[80vw] h-[60vh] md:w-[60vw] md:h-[70vh] border-[40px] md:border-[80px] border-[#0f1115] rounded-t-full shadow-2xl relative bg-black/10 backdrop-blur-sm overflow-hidden flex items-end justify-center">
              <div className="absolute inset-0 border-b-2 border-brand-gold/20"></div>
           </div>
        </div>

        {/* Layer 1: Text Overlay (Appears then zooms past) */}
        <div 
          className="absolute z-30 text-center px-4"
          style={{
             opacity: 1 - scrollProgress * 3, // Fades out quickly
             transform: `scale(${1 + scrollProgress * 2}) translateY(${scrollProgress * -100}px)`
          }}
        >
           <h2 className="font-serif text-5xl md:text-8xl text-transparent bg-clip-text bg-gradient-to-b from-brand-gold to-yellow-600 font-bold drop-shadow-2xl">
             Step Into Luxury
           </h2>
           <p className="text-white text-xl mt-4 tracking-[0.5em] uppercase font-light">
             The AGS Experience
           </p>
        </div>

        {/* Floating Particles (Z-Axis Depth) */}
        <div 
           className="absolute inset-0 z-25 pointer-events-none"
           style={{ transform: `scale(${1 + scrollProgress * 5})` }}
        >
           <div className="absolute top-1/4 left-1/4 w-2 h-2 bg-brand-gold rounded-full opacity-60"></div>
           <div className="absolute top-3/4 right-1/4 w-3 h-3 bg-white rounded-full opacity-40"></div>
           <div className="absolute bottom-1/4 left-1/2 w-1 h-1 bg-brand-gold rounded-full opacity-80"></div>
        </div>

        {/* Final Reveal Text (Shows when fully zoomed in) */}
