        <Suspense fallback={<div className="h-96 w-full bg-slate-50"></div>}>
           <BeforeAfter />
        </Suspense>

        <Suspense fallback={<div className="h-96 w-full bg-white"></div>}>
           <LocalProjects />
        </Suspense>

        <Suspense fallback={<div className="h-96 w-full bg-brand-dark"></div>}>
