          {activeSection === 'contact' && <span className="absolute -bottom-2 left-1/2 -translate-x-1/2 w-1 h-1 bg-brand-gold rounded-full"></span>}
        </button>

      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
