              <WhyChooseUs />
           </Suspense>
        </LazySection>

        <LazySection minHeight="500px">
           <Suspense fallback={<div className="h-96 w-full bg-white" />}>
              <BeforeAfter />
           </Suspense>
        </LazySection>

        <LazySection minHeight="600px">
           <Suspense fallback={<div className="h-96 w-full bg-white" />}>
              <LocalProjects />
           </Suspense>
        </LazySection>

        <LazySection minHeight="500px" className="bg-brand-dark">
