type WidgetState = 'HIDDEN' | 'TYPING' | 'VISIBLE' | 'MINIMIZED';

export const FloatingWidget: React.FC = () => {
  const [stage, setStage] = useState<WidgetState>('HIDDEN');
  const [hasBeenClosed, setHasBeenClosed] = useState(false);

  useEffect(() => {
    if (hasBeenClosed) return;

    // Timeline:
    // 0s: Hidden
    // 4s: Starts "Typing"
    // 6.5s: Shows Message

    const typingTimer = setTimeout(() => {
      setStage('TYPING');
    }, 4000);

    const messageTimer = setTimeout(() => {
      setStage('VISIBLE');
    }, 6500);

    return () => {
      clearTimeout(typingTimer);
      clearTimeout(messageTimer);
    };
  }, [hasBeenClosed]);

  const handleClose = () => {
    // Instead of hiding completely, minimize it
    setStage('MINIMIZED');
    setHasBeenClosed(true);
    // Removed dispatchEvent to avoid duplicate notifications on MobileNav
    // window.dispatchEvent(new CustomEvent('ags-popup-closed'));
  };

  const handleOpen = () => {
    setStage('VISIBLE');
