  if (stage === 'HIDDEN') return null;

  return (
    <div className="fixed bottom-24 right-4 md:bottom-8 md:right-8 z-[60] flex flex-col items-end pointer-events-none">

       <div className="pointer-events-auto flex items-end gap-3 max-w-[calc(100vw-2rem)] sm:max-w-[350px]">

