import React, { useState, useEffect } from 'react';
import { Phone, X } from 'lucide-react';

type WidgetState = 'HIDDEN' | 'TYPING' | 'VISIBLE' | 'MINIMIZED';

export const FloatingWidget: React.FC = () => {
  const [stage, setStage] = useState<WidgetState>('HIDDEN');
  const [hasBeenClosed, setHasBeenClosed] = useState(false);

  useEffect(() => {
    if (hasBeenClosed) return;

    // Timeline:
    // 0s: Hidden
    // 4s: Starts "Typing"
    // 6.5s: Shows Message

    const typingTimer = setTimeout(() => {
      setStage('TYPING');
    }, 4000);

    const messageTimer = setTimeout(() => {
      setStage('VISIBLE');
    }, 6500);

    return () => {
      clearTimeout(typingTimer);
      clearTimeout(messageTimer);
    };
  }, [hasBeenClosed]);

  const handleClose = () => {
    setStage('MINIMIZED');
    setHasBeenClosed(true);
  };

  const handleOpen = () => {
    setStage('VISIBLE');
  };

  if (stage === 'HIDDEN') return null;

  return (
    // MAIN CONTAINER: Fixed Bottom Right.
    // Mobile: Bottom-24 (above nav), Right-2 (tight to edge)
    // Desktop: Bottom-8, Right-8
    <div className="fixed bottom-24 right-2 md:bottom-8 md:right-8 z-[60] flex flex-col items-end pointer-events-none">

       {/* INNER CONTAINER: Stack Vertically (Reverse) */}
       <div className="pointer-events-auto flex flex-col-reverse items-end gap-2 md:gap-3 w-auto">

          {/* 1. AVATAR (Bottom Element) */}
          <div 
            className={`relative flex-shrink-0 transition-transform duration-300 ${stage === 'MINIMIZED' ? 'cursor-pointer hover:scale-110' : ''}`}
            onClick={stage === 'MINIMIZED' ? handleOpen : undefined}
          >
             {/* Mobile: w-9 h-9 (36px) | Desktop: w-14 h-14 (56px) */}
             <div className="w-9 h-9 md:w-14 md:h-14 rounded-full border-2 border-white shadow-lg overflow-hidden relative z-10">
                <img 
                  src="https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&q=80&w=200" 
                  alt="AGS Design Specialist" 
                  className="w-full h-full object-cover"
                />
             </div>

             {/* Notification Badge (Only when MINIMIZED) */}
             {stage === 'MINIMIZED' && (
               <div className="absolute -top-1 -right-1 z-20 flex h-4 w-4 md:h-5 md:w-5 animate-[bounce_2s_infinite]">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                  <span className="relative inline-flex rounded-full h-full w-full bg-red-500 text-white text-[9px] md:text-[10px] font-bold items-center justify-center border-2 border-white">
                    1
                  </span>
               </div>
             )}

             {/* Online Status Dot (Only when NOT minimized) */}
             {stage !== 'MINIMIZED' && (
                <div className="absolute bottom-0 right-0 w-2.5 h-2.5 md:w-3.5 md:h-3.5 bg-green-500 border-2 border-white rounded-full z-20"></div>
             )}
          </div>

          {/* 2. CHAT BUBBLE (Top Element) */}
          {stage !== 'MINIMIZED' && (
            <div className="origin-bottom-right animate-[scaleIn_0.3s_ease-out] flex flex-col items-end shadow-xl rounded-2xl rounded-br-none border border-gray-100 bg-white overflow-hidden transition-all duration-300 max-w-[200px] md:max-w-[280px]">

              {stage === 'TYPING' ? (
                // TYPING STATE
                <div className="p-2 md:p-3 flex items-center gap-1.5">
                   <span className="text-[9px] md:text-[10px] text-gray-400 font-medium mr-1">Jessica is typing</span>
                   <div className="flex gap-1">
                      <span className="w-1 h-1 bg-gray-400 rounded-full animate-bounce"></span>
                      <span className="w-1 h-1 bg-gray-400 rounded-full animate-bounce [animation-delay:0.15s]"></span>
                      <span className="w-1 h-1 bg-gray-400 rounded-full animate-bounce [animation-delay:0.3s]"></span>
                   </div>
                </div>
              ) : (
                // VISIBLE MESSAGE STATE
                // Mobile: p-3 | Desktop: p-4
                <div className="relative p-3 md:p-5 w-full">
                   <button 
                      onClick={handleClose}
                      className="absolute top-2 right-2 text-gray-300 hover:text-gray-500 p-1"
                      aria-label="Close chat"
                   >
                      <X size={12} className="md:w-4 md:h-4" />
                   </button>

                   <div className="mb-1 text-left">
                      <span className="text-[8px] md:text-[10px] font-bold uppercase tracking-widest text-brand-gold">Design Specialist</span>
                      {/* Mobile: Text-xs | Desktop: Text-sm */}
                      <h4 className="font-serif font-bold text-brand-dark text-xs md:text-sm leading-tight mt-0.5">
                         Hi! Thinking about a new patio?
                      </h4>
                   </div>

                   {/* Mobile: Text-[10px] | Desktop: Text-xs */}
                   <p className="text-[10px] md:text-xs text-gray-500 mb-3 leading-relaxed text-left">
                      I can schedule a free estimate or 3D design consultation for you.
                   </p>

                   {/* INCREASED BUTTON SIZE AND PADDING FOR BETTER TAP TARGET */}
                   <a 
                     href="tel:6784287630" 
                     className="flex items-center justify-center gap-2 bg-brand-dark text-white hover:bg-brand-gold transition-colors py-3 px-4 rounded-md font-bold text-xs uppercase tracking-wide w-full shadow-md group"
                   >
                      <Phone size={14} className="group-hover:rotate-12 transition-transform" />
                      Call: (678) 428-7630
                   </a>
                </div>
              )}
            </div>
          )}
       </div>

    </div>
  );
};

import React, { Component, useEffect, useState, useRef, Suspense, ReactNode, ErrorInfo } from 'react';
import { Header } from './components/Header';
import { Hero } from './components/Hero';

// --- COMPONENT CHUNKS ---
const ZParallaxShowcase = React.lazy(() => import('./components/ZParallaxShowcase').then(module => ({ default: module.ZParallaxShowcase })));

// Block 1: Core Value Proposition
const Services = React.lazy(() => import('./components/Services').then(module => ({ default: module.Services })));
const WhyChooseUs = React.lazy(() => import('./components/WhyChooseUs').then(module => ({ default: module.WhyChooseUs })));

// Block 2: Visual Proof
const BeforeAfter = React.lazy(() => import('./components/BeforeAfter').then(module => ({ default: module.BeforeAfter })));
const LocalProjects = React.lazy(() => import('./components/LocalProjects').then(module => ({ default: module.LocalProjects })));
const DayNightSlider = React.lazy(() => import('./components/DayNightSlider').then(module => ({ default: module.DayNightSlider })));

// Block 3: Trust & Conversion
const Testimonials = React.lazy(() => import('./components/Testimonials').then(module => ({ default: module.Testimonials })));
const FAQ = React.lazy(() => import('./components/FAQ').then(module => ({ default: module.FAQ })));
const Contact = React.lazy(() => import('./components/Contact').then(module => ({ default: module.Contact })));
const Footer = React.lazy(() => import('./components/Footer').then(module => ({ default: module.Footer })));

// Aux
const MobileNav = React.lazy(() => import('./components/MobileNav').then(module => ({ default: module.MobileNav })));
const FloatingWidget = React.lazy(() => import('./components/FloatingWidget').then(module => ({ default: module.FloatingWidget })));
const ExitIntentPopup = React.lazy(() => import('./components/ExitIntentPopup').then(module => ({ default: module.ExitIntentPopup })));

// --- ERROR BOUNDARY ---
interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

// Prevents the entire site from crashing if one lazy chunk fails to load
class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(_: Error): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return <div className="p-8 text-center text-gray-500 text-sm">Content temporarily unavailable. Please refresh.</div>;
    }
    return this.props.children;
  }
}

// --- LIGHTWEIGHT LAZY WRAPPER ---
const LazyBlock: React.FC<{ children: React.ReactNode, minHeight?: string }> = ({ children, minHeight = "500px" }) => {
  const [isVisible, setIsVisible] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // 1. Immediate mobile check to avoid waiting
    if (typeof window !== 'undefined' && window.scrollY > 200) {
       // If user already scrolled down on reload, show immediately
       setIsVisible(true);
       return;
    }

    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) {
        setIsVisible(true);
        observer.disconnect();
      }
    }, { rootMargin: "600px" }); // Huge margin to load well before user arrives

    if (ref.current) observer.observe(ref.current);

    // Safety fallback
    const timer = setTimeout(() => setIsVisible(true), 3000);

    return () => {
        observer.disconnect();
        clearTimeout(timer);
    };
  }, []);

  return (
    <div ref={ref} style={{ minHeight: isVisible ? 'auto' : minHeight }}>
      {isVisible ? children : null}
    </div>
  );
};

const App: React.FC = () => {
  const [isServiceModalOpen, setIsServiceModalOpen] = useState(false);

  // Global Animation Observer (Optimized: Single Instance)
  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          entry.target.classList.remove('fade-in-section'); // Cleanup class
        }
      });
    }, { threshold: 0.1 });

    // Attach to body to catch new elements as they hydrate
    const mutationObserver = new MutationObserver((mutations) => {
      mutations.forEach(mutation => {
        mutation.addedNodes.forEach(node => {
          if (node instanceof HTMLElement) {
             if (node.classList.contains('fade-in-section')) observer.observe(node);
             node.querySelectorAll('.fade-in-section').forEach(el => observer.observe(el));
          }
        });
      });
    });

    mutationObserver.observe(document.body, { childList: true, subtree: true });
    return () => { observer.disconnect(); mutationObserver.disconnect(); }
  }, []);

  return (
    <div className="font-sans antialiased text-brand-dark bg-slate-50 pb-24 md:pb-0">
      <Header isHidden={isServiceModalOpen} />

      <main>
        {/* CRITICAL: Hero Loads Instantly */}
        <Hero />

        {/* PRIORITY 1: Immediate Below Fold (No LazyBlock wrapper to prevent gaps) */}
        <ErrorBoundary>
          <Suspense fallback={<div className="h-[85vh] bg-[#0f1115] w-full" />}>
             <ZParallaxShowcase />
          </Suspense>
        </ErrorBoundary>

        {/* PRIORITY 2: Core Services (Batched) */}
        <LazyBlock minHeight="1000px">
           <ErrorBoundary>
              <Suspense fallback={<div className="h-96 w-full bg-slate-50 animate-pulse" />}>
                 <Services onModalChange={setIsServiceModalOpen} />
                 <WhyChooseUs />
              </Suspense>
           </ErrorBoundary>
        </LazyBlock>

        {/* PRIORITY 3: Visual Proof (Batched) */}
        <LazyBlock minHeight="1200px">
           <ErrorBoundary>
              <Suspense fallback={<div className="h-96 w-full bg-white" />}>
                 <BeforeAfter />
                 <LocalProjects />
                 <DayNightSlider />
              </Suspense>
           </ErrorBoundary>
        </LazyBlock>

        {/* PRIORITY 4: Trust & Contact (Batched) */}
        <LazyBlock minHeight="1000px">
           <ErrorBoundary>
              <Suspense fallback={<div className="h-96 w-full bg-brand-light" />}>
                 <Testimonials />
                 <FAQ />
                 <Contact />
              </Suspense>
           </ErrorBoundary>
        </LazyBlock>
      </main>

      <LazyBlock minHeight="300px">
         <ErrorBoundary>
            <Suspense fallback={<div className="h-40 w-full bg-brand-dark" />}>
               <Footer />
            </Suspense>
         </ErrorBoundary>
      </LazyBlock>

      {/* AUXILIARY: Load last, completely separate */}
      <Suspense fallback={null}>
         <FloatingWidget />
         <MobileNav />
         <ExitIntentPopup />
      </Suspense>
    </div>
  );
};

