export const ZParallaxShowcase: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const height = rect.height - window.innerHeight;
      const top = -rect.top;
      const progress = Math.max(0, Math.min(1, top / height));
      requestAnimationFrame(() => setScrollProgress(progress));
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <section ref={containerRef} className="relative h-[200vh] bg-white overflow-hidden">

      {/* Sticky Container */}
      <div className="sticky top-0 h-screen w-full overflow-hidden flex items-center justify-center">

        {/* Background Image (The Destination) - Starts small, grows to fill */}
        <div 
           className="absolute inset-0 w-full h-full"
           style={{
             transform: `scale(${0.8 + (scrollProgress * 0.2)})`, // Subtle zoom
             filter: `brightness(${0.5 + (scrollProgress * 0.5)})`, // Brightens as you scroll
           }}
        >
            <img 
              src="https://i.imgur.com/6rQRJxs.jpeg" 
              alt="Magnificent Outdoor Living" 
              className="w-full h-full object-cover"
            />
            {/* Elegant overlay gradient */}
            <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" style={{ opacity: 1 - scrollProgress }}></div>
        </div>

        {/* Text Overlay (Fades out as image takes over) */}
        <div 
          className="absolute z-30 text-center px-4 w-full flex flex-col items-center justify-center h-full pointer-events-none mix-blend-overlay"
          style={{
             opacity: Math.max(0, 1 - scrollProgress * 1.5), 
             transform: `translateY(${scrollProgress * -100}px)`
          }}
        >
           <span className="text-white font-bold tracking-[0.4em] uppercase text-xs md:text-sm mb-6 border-b border-white/50 pb-2">
             The AGS Difference
           </span>
           <h2 className="font-serif text-6xl md:text-9xl text-white font-medium leading-none tracking-tight">
             Timeless <br/> Stone
           </h2>
        </div>

        {/* Reveal Mask (White borders opening up) */}
        <div 
          className="absolute inset-0 pointer-events-none border-[50px] md:border-[100px] border-white z-20 transition-transform duration-75"
          style={{
             transform: `scale(${1 + scrollProgress * 5})`,
             opacity: Math.max(0, 1 - scrollProgress), // Fades out eventually
          }}
        ></div>

        {/* Scroll Prompt */}
        <div 
           className="absolute bottom-12 z-40 text-white flex flex-col items-center gap-3 transition-opacity duration-300"
           style={{ opacity: scrollProgress > 0.1 ? 0 : 1 }}
        >
           <div className="h-16 w-px bg-white/50"></div>
           <span className="text-[10px] uppercase tracking-widest font-bold">Discover</span>
        </div>

      </div>
    </section>
  );
};

