import React, { useEffect, useRef, useState } from 'react';

export const ZParallaxShowcase: React.FC = () => {
  const sectionRef = useRef<HTMLElement>(null);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      if (!sectionRef.current) return;

      const rect = sectionRef.current.getBoundingClientRect();
      const windowHeight = window.innerHeight;
      const elementHeight = rect.height;

      // Calculate progress based on how far the section has scrolled relative to the viewport
      // When rect.top is 0 (section hits top of screen), progress starts increasing
      // We want the effect to complete before the section scrolls away fully.

      const scrollDistance = -rect.top;
      const totalDistance = elementHeight - windowHeight;

      let newProgress = scrollDistance / totalDistance;
      newProgress = Math.max(0, Math.min(1, newProgress));

      // Use requestAnimationFrame for smoother state updates during scroll
      requestAnimationFrame(() => setProgress(newProgress));
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Visual calculations
  // Clip Path: Starts at 15% (small circle) and expands to 150% (fully open)
  const clipSize = 15 + (progress * 135);
  const opacity = Math.max(0, 1 - progress * 2.5); // Fades out quickly
  const scale = 1 + (1 - progress) * 0.2; // Slight zoom out effect on image

  return (
    <section ref={sectionRef} className="relative h-[250vh] bg-brand-dark">
      <div className="sticky top-0 h-screen w-full overflow-hidden flex items-center justify-center">

        {/* Background Text (Visible before image opens fully) */}
        <div 
            className="absolute z-20 text-center text-white pointer-events-none mix-blend-difference px-4"
            style={{ 
                opacity: opacity,
                transform: `translateY(${progress * -50}px) scale(${1 + progress * 0.5})` 
            }}
        >
            <p className="text-xs md:text-sm font-bold uppercase tracking-[0.5em] mb-4 text-brand-gold">Welcome to</p>
            <h2 className="text-6xl md:text-9xl font-serif leading-none tracking-tighter">
              AGS <br/>
              <span className="text-4xl md:text-6xl italic font-light tracking-normal">Experience</span>
            </h2>
        </div>

        {/* The Reveal Image Container */}
        <div 
          className="absolute inset-0 w-full h-full bg-brand-dark"
          style={{
            clipPath: `circle(${clipSize}% at 50% 50%)`,
            transition: 'clip-path 0.1s linear' // Smooth out the raw scroll jaggedness slightly
          }}
        >
          <img 
            src="https://i.imgur.com/KPsOHF5h.webp" 
            alt="Luxury Backyard Transformation" 
            className="w-full h-full object-cover"
            style={{ transform: `scale(${scale})` }}
          />

          {/* Overlay to darken image slightly for text contrast once fully open */}
          <div className="absolute inset-0 bg-black/20"></div>

          {/* Content revealed at the bottom when fully open */}
          <div 
             className="absolute bottom-12 left-0 w-full text-center transition-opacity duration-500"
             style={{ opacity: progress > 0.8 ? 1 : 0 }}
          >
             <p className="text-white/90 text-lg font-serif italic">Designing for the ages.</p>
          </div>
        </div>

        {/* Scroll Indicator (Fades out) */}
        <div 
            className="absolute bottom-8 left-1/2 -translate-x-1/2 text-white/50 flex flex-col items-center gap-2 transition-opacity duration-300"
            style={{ opacity: opacity }}
        >
            <span className="text-[10px] uppercase tracking-widest">Scroll to Open</span>
            <div className="w-px h-8 bg-white/30"></div>
        </div>

      </div>
    </section>
  );
};

