export const ZParallaxShowcase: React.FC = () => {
  const sectionRef = useRef<HTMLElement>(null);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      if (!sectionRef.current) return;

      const rect = sectionRef.current.getBoundingClientRect();
      const windowHeight = window.innerHeight;
      const elementHeight = rect.height;

      const scrollDistance = -rect.top;
      const totalDistance = elementHeight - windowHeight;

      let newProgress = scrollDistance / totalDistance;
      newProgress = Math.max(0, Math.min(1, newProgress));

      requestAnimationFrame(() => setProgress(newProgress));
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const clipSize = 15 + (progress * 135);
  const opacity = Math.max(0, 1 - progress * 2.5); 
  const scale = 1 + (1 - progress) * 0.2; 

  return (
    // REDUCED HEIGHT: h-[200vh] instead of h-[250vh]
    <section ref={sectionRef} className="relative h-[200vh] bg-brand-dark">
      <div className="sticky top-0 h-screen w-full overflow-hidden flex items-center justify-center">

        {/* Background Text */}
        <div 
            className="absolute z-20 text-center text-white pointer-events-none mix-blend-difference px-4"
            style={{ 
                opacity: opacity,
                transform: `translateY(${progress * -50}px) scale(${1 + progress * 0.5})` 
            }}
