        {/* The Reveal Image Container */}
        <div 
          className="absolute inset-0 w-full h-full bg-brand-dark"
          style={{
            clipPath: `circle(${clipSize}% at 50% 50%)`,
            transition: 'clip-path 0.1s linear'
          }}
        >
          <img 
            src="https://i.imgur.com/KPsOHF5h.webp" 
            alt="Luxury Backyard Transformation" 
            className="w-full h-full object-cover"
