// --- 3D ENGINE COMPONENT ---
const Paver3DViewer = () => {
  const [rotation, setRotation] = useState({ x: 60, z: 45 });
  const [zoom, setZoom] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);
  const lastMouse = useRef({ x: 0, y: 0 });

  const handleMouseDown = (e: React.MouseEvent) => {
    isDragging.current = true;
    lastMouse.current = { x: e.clientX, y: e.clientY };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging.current) return;
    const deltaX = e.clientX - lastMouse.current.x;
    const deltaY = e.clientY - lastMouse.current.y;
    setRotation(prev => ({
      x: Math.max(0, Math.min(90, prev.x - deltaY * 0.5)), 
      z: prev.z + deltaX * 0.5
    }));
    lastMouse.current = { x: e.clientX, y: e.clientY };
  };

  const handleMouseUp = () => { isDragging.current = false; };
  const handleWheel = (e: React.WheelEvent) => {
    e.stopPropagation();
    setZoom(prev => Math.max(0.5, Math.min(2, prev - e.deltaY * 0.001)));
  };

  const pavers = [];
  const rows = 6;
  const cols = 6;
  for (let i = -rows/2; i < rows/2; i++) {
    for (let j = -cols/2; j < cols/2; j++) {
       pavers.push({ x: i * 60, y: j * 35 + (i % 2 ? 17.5 : 0), color: '#e2e8f0' });
    }
  }

  return (
    <div 
      ref={containerRef}
      className="w-full h-full bg-gray-100 relative overflow-hidden cursor-move flex items-center justify-center rounded-l-2xl md:rounded-l-none select-none border-r border-gray-200"
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onWheel={handleWheel}
    >
       <div 
         className="relative w-0 h-0"
         style={{
            transformStyle: 'preserve-3d',
            transform: `perspective(1000px) rotateX(${rotation.x}deg) rotateZ(${rotation.z}deg) scale(${zoom})`
         }}
       >
          <div className="absolute bg-gray-300 border-4 border-white shadow-xl" style={{ width: '400px', height: '400px', transform: 'translate(-50%, -50%) translateZ(-10px)' }} />
          {pavers.map((p, idx) => (
             <div key={idx} className="absolute" style={{ width: '56px', height: '30px', transform: `translate3d(${p.x}px, ${p.y}px, 0)`, transformStyle: 'preserve-3d' }}>
                <div className="absolute inset-0 bg-stone-200 border border-stone-300" style={{ transform: 'translateZ(8px)' }} />
                <div className="absolute bottom-0 left-0 w-full h-[8px] bg-stone-400 origin-bottom" style={{ transform: 'rotateX(-90deg)' }}></div>
                <div className="absolute right-0 top-0 h-full w-[8px] bg-stone-300 origin-right" style={{ transform: 'rotateY(90deg)' }}></div>
                <div className="absolute left-0 top-0 h-full w-[8px] bg-stone-300 origin-left" style={{ transform: 'rotateY(-90deg)' }}></div>
             </div>
          ))}
       </div>
       <div className="absolute bottom-6 right-6 flex flex-col gap-2 pointer-events-none">
          <div className="bg-white/80 backdrop-blur-md p-2 rounded shadow-sm text-brand-dark text-[10px] font-bold uppercase tracking-widest flex items-center gap-2 border border-gray-200">
             <Move3d size={14} className="text-brand-gold" /> Interactive
          </div>
       </div>
    </div>
  );
};

