export const ZParallaxShowcase: React.FC = () => {
  const sectionRef = useRef<HTMLElement>(null);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      if (!sectionRef.current) return;

      const rect = sectionRef.current.getBoundingClientRect();
      const windowHeight = window.innerHeight;
      const elementHeight = rect.height;

      const scrollDistance = -rect.top;
      // We want the effect to finish slightly before the bottom
      const totalDistance = elementHeight - windowHeight;

      let newProgress = scrollDistance / totalDistance;
      newProgress = Math.max(0, Math.min(1, newProgress));

      requestAnimationFrame(() => setProgress(newProgress));
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Visual calculations
  const clipSize = 15 + (progress * 135);
  const opacity = Math.max(0, 1 - progress * 3); // Faster fade out so image takes over
  const scale = 1 + (1 - progress) * 0.1; // Subtle zoom out

  return (
    <section ref={sectionRef} className="relative h-[200vh] bg-brand-dark">
      <div className="sticky top-0 h-screen w-full overflow-hidden flex items-center justify-center">

        {/* SEO OPTIMIZED INTRO TEXT */}
        <div 
            className="absolute z-20 text-center text-white pointer-events-none mix-blend-difference px-4 w-full"
            style={{ 
                opacity: opacity,
                transform: `translateY(${progress * -50}px) scale(${1 + progress * 0.5})` 
            }}
        >
            <p className="text-xs md:text-sm font-bold uppercase tracking-[0.3em] mb-4 text-brand-gold">
              Atlanta's Premier Hardscapes
            </p>
            <h1 className="text-5xl md:text-8xl font-serif leading-none tracking-tighter">
              AGS <br/>
              <span className="text-3xl md:text-6xl italic font-light tracking-normal opacity-90">
                Stones & Pavers
              </span>
            </h1>
            <p className="mt-6 text-xs md:text-sm font-light text-gray-300 max-w-md mx-auto leading-relaxed hidden md:block">
               Serving Duluth, Alpharetta, and Roswell with luxury masonry and outdoor living solutions.
            </p>
        </div>

        {/* The Reveal Image Container */}
        <div 
          className="absolute inset-0 w-full h-full bg-brand-dark"
          style={{
            clipPath: `circle(${clipSize}% at 50% 50%)`,
            transition: 'clip-path 0.1s linear'
          }}
        >
          {/* NEW STUNNING IMAGE - Luxury Pool Deck at Twilight */}
          <img 
            src="https://images.unsplash.com/photo-1576013551627-5cc20b368619?q=80&w=2670&auto=format&fit=crop" 
            alt="Luxury Travertine Pool Deck and Paver Patio in Atlanta" 
            className="w-full h-full object-cover"
            style={{ transform: `scale(${scale})` }}
          />

          <div className="absolute inset-0 bg-black/20"></div>

          {/* Footer Text Revealed - SEO Rich */}
          <div 
             className="absolute bottom-12 left-0 w-full text-center transition-all duration-700 delay-100"
             style={{ 
               opacity: progress > 0.8 ? 1 : 0,
               transform: `translateY(${progress > 0.8 ? 0 : 20}px)`
             }}
          >
             <h3 className="text-white text-xl md:text-2xl font-serif italic mb-2">Designing for the Ages</h3>
             <p className="text-brand-gold text-xs font-bold uppercase tracking-widest">
               Retaining Walls • Pavers • Outdoor Living
             </p>
          </div>
        </div>

        {/* Scroll Indicator */}
        <div 
            className="absolute bottom-8 left-1/2 -translate-x-1/2 text-white/50 flex flex-col items-center gap-2 transition-opacity duration-300"
            style={{ opacity: opacity }}
        >
            <span className="text-[10px] uppercase tracking-widest animate-pulse">Scroll to Reveal</span>
