  const [formData, setFormData] = useState({ name: '', phone: '', email: '', service: '' });

  useEffect(() => {
    const checkMobile = () => {
        setIsMobile(window.innerWidth < 768);
    };
    checkMobile();
    window.addEventListener('resize', checkMobile);

    let animationFrameId: number;

