export const DayNightSlider: React.FC = () => {
  const [sliderPosition, setSliderPosition] = useState(50);
  const containerRef = useRef<HTMLDivElement>(null);
  const sectionRef = useRef<HTMLElement>(null);
  const isDragging = useRef(false);

  // Determine 'Night Mode' dominance based on slider position
  // If slider is < 50%, we are revealing more Night (since Night is the background/right side in this logic usually, 
  // actually let's make Day Left (width) and Night Right (background)).
  // Standard Comparison: 
  // Layer 1 (Bottom): Night Image (Full width)
  // Layer 2 (Top): Day Image (Clipped width)
  // So if sliderPosition is 100%, we see full Day. If 0%, we see full Night.
  const isNightDominant = sliderPosition < 40;

  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.1 });

    if (sectionRef.current) {
        sectionRef.current.querySelectorAll('.fade-in-section').forEach(el => observer.observe(el));
    }

    return () => observer.disconnect();
  }, []);

  const handleMove = (clientX: number) => {
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect();
      const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
      const percentage = (x / rect.width) * 100;
      setSliderPosition(percentage);
    }
  };

  const handleMouseDown = () => { isDragging.current = true; };
  const handleMouseUp = () => { isDragging.current = false; };
  const handleMouseMove = (e: React.MouseEvent) => { if (isDragging.current) handleMove(e.clientX); };
  const handleTouchMove = (e: React.TouchEvent) => { handleMove(e.touches[0].clientX); };

  useEffect(() => {
    const handleGlobalMouseUp = () => { isDragging.current = false; };
    window.addEventListener('mouseup', handleGlobalMouseUp);
    return () => window.removeEventListener('mouseup', handleGlobalMouseUp);
  }, []);

  return (
    <section 
        ref={sectionRef} 
        className={`pt-32 pb-48 relative overflow-hidden transition-colors duration-700 ease-in-out ${isNightDominant ? 'bg-[#0f1115] text-white' : 'bg-white text-brand-dark'}`}
    >

      {/* Ambient Background Effects */}
      <div className={`absolute inset-0 transition-opacity duration-1000 pointer-events-none ${isNightDominant ? 'opacity-100' : 'opacity-0'}`}>
         <div className="absolute top-1/2 left-1/4 w-[600px] h-[600px] bg-blue-900/10 rounded-full blur-[150px]"></div>
      </div>
      <div className={`absolute inset-0 transition-opacity duration-1000 pointer-events-none ${!isNightDominant ? 'opacity-100' : 'opacity-0'}`}>
         <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-brand-gold/5 rounded-full blur-[150px]"></div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
        <div className="grid lg:grid-cols-2 gap-16 items-center">

           {/* Text Content */}
           <div className="fade-in-section">
              <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full border border-brand-gold/30 bg-brand-gold/10 text-brand-gold text-xs font-bold uppercase tracking-widest mb-6">
                 <Lightbulb size={14} /> Day to Night Transformation
              </div>

              <h2 className="font-serif text-4xl md:text-5xl font-bold mb-6 transition-colors duration-700">
                Your Oasis Doesn't Sleep <br/>
                <span className="text-brand-gold">When The Sun Sets.</span>
              </h2>

              <p className={`text-lg leading-relaxed mb-8 transition-colors duration-700 ${isNightDominant ? 'text-gray-400' : 'text-gray-600'}`}>
                 We design outdoor living spaces that are just as magical at night. Drag the slider to see how integrated LED lighting transforms your patio into an evening sanctuary.
              </p>

              <div className={`border p-6 rounded-2xl backdrop-blur-sm transition-all duration-700 ${isNightDominant ? 'bg-white/5 border-white/10' : 'bg-gray-50 border-gray-100'}`}>
                 <h4 className="font-bold mb-4">Lighting Services Include:</h4>
                 <ul className="grid grid-cols-2 gap-4">
                    {['Pathway Lighting', 'Up-lighting Trees', 'Retaining Wall Lights', 'Pool Deck Ambience'].map((item, i) => (
                       <li key={i} className={`flex items-center gap-2 text-sm transition-colors duration-700 ${isNightDominant ? 'text-gray-300' : 'text-gray-600'}`}>
                          <div className={`w-2 h-2 rounded-full ${isNightDominant ? 'bg-brand-gold shadow-[0_0_8px_rgba(212,175,55,0.8)]' : 'bg-gray-400'}`}></div>
                          {item}
                       </li>
                    ))}
                 </ul>
              </div>

              <div className={`mt-8 flex items-center gap-2 text-xs font-bold uppercase tracking-widest animate-pulse ${isNightDominant ? 'text-brand-gold' : 'text-brand-dark/50'}`}>
                  <ArrowLeft size={14} /> Drag Slider to Compare <ArrowRight size={14} />
              </div>
           </div>

           {/* Interactive Slider */}
           <div className="relative h-[400px] md:h-[500px] rounded-3xl overflow-hidden shadow-2xl border-4 border-white/10 group fade-in-section delay-200 select-none cursor-ew-resize">
              <div 
                  ref={containerRef}
                  className="relative w-full h-full"
                  onMouseDown={handleMouseDown}
                  onMouseMove={handleMouseMove}
                  onTouchMove={handleTouchMove}
              >
                  {/* NIGHT IMAGE (Bottom Layer - Revealed on Right) */}
                  <div className="absolute inset-0">
                      <img 
                         src="https://i.imgur.com/skbC8RZ.png"
                         alt="Patio Night"
                         className="w-full h-full object-cover grayscale-[10%] brightness-90 contrast-125"
                         draggable={false}
                      />
                      {/* Night Label */}
                      <div className="absolute top-6 right-6 bg-brand-dark/80 backdrop-blur-md text-brand-gold px-4 py-1.5 rounded-full text-xs font-bold uppercase tracking-widest shadow-lg flex items-center gap-2 z-10">
                          <Moon size={12} fill="currentColor" /> Night Mode
                      </div>

                      {/* Lighting Effects (Only visible on Night layer) */}
                      <div className="absolute bottom-1/4 left-1/4 w-32 h-32 bg-orange-500/30 blur-[60px] rounded-full mix-blend-screen animate-pulse pointer-events-none"></div>
                      <div className="absolute top-1/3 right-1/4 w-40 h-40 bg-blue-500/20 blur-[80px] rounded-full mix-blend-screen pointer-events-none"></div>
                  </div>

                  {/* DAY IMAGE (Top Layer - Revealed on Left) */}
                  <div 
                     className="absolute inset-0 overflow-hidden border-r-2 border-white/50"
                     style={{ width: `${sliderPosition}%` }}
                  >
                      <img 
                        src="https://i.imgur.com/lCsQQavh.webp" 
                        alt="Patio Day" 
                        className="w-full h-full object-cover max-w-none"
                        style={{ width: containerRef.current?.offsetWidth || '100%' }}
                        draggable={false}
                      />
                      {/* Day Label */}
                      <div className="absolute top-6 left-6 bg-white/90 backdrop-blur-md text-brand-dark px-4 py-1.5 rounded-full text-xs font-bold uppercase tracking-widest shadow-lg flex items-center gap-2">
                          <Sun size={12} className="text-brand-gold" fill="currentColor" /> Day Mode
                      </div>
                  </div>

                  {/* Draggable Handle */}
                  <div 
                    className="absolute top-0 bottom-0 w-0 z-30"
                    style={{ left: `${sliderPosition}%` }}
                  >
                     <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-14 h-14 bg-white rounded-full shadow-[0_0_30px_rgba(0,0,0,0.5)] flex items-center justify-center text-brand-dark transform transition-transform group-hover:scale-110 border-4 border-white/20">
                        {sliderPosition > 50 ? (
                            <Sun className="w-6 h-6 text-brand-gold" fill="currentColor" />
                        ) : (
                            <Moon className="w-6 h-6 text-brand-dark" fill="currentColor" />
                        )}
                     </div>
                  </div>
              </div>
           </div>

        </div>
      </div>
    </section>
  );
};

import React, { useEffect, useRef, useState } from 'react';
