import React, { useState, useEffect } from 'react';
import { Home, Layers, Phone, Mail, Image } from 'lucide-react';

export const MobileNav: React.FC = () => {
  const [activeSection, setActiveSection] = useState('home');
  const [showNotification, setShowNotification] = useState(false);

  useEffect(() => {
    const observerOptions = {
      root: null,
      rootMargin: '0px',
      threshold: 0.3
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          setActiveSection(entry.target.id);
        }
      });
    }, observerOptions);

    const sections = ['home', 'services', 'portfolio', 'contact'];
    sections.forEach(id => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });

    const handlePopupClose = () => {
      setShowNotification(true);
    };

    window.addEventListener('ags-popup-closed', handlePopupClose);

    return () => {
      observer.disconnect();
      window.removeEventListener('ags-popup-closed', handlePopupClose);
    };
  }, []);

  const scrollTo = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const NavItem = ({ id, icon: Icon, label }: { id: string, icon: any, label: string }) => {
    const isActive = activeSection === id;
    return (
      <button 
        onClick={() => scrollTo(id)}
        className={`flex flex-col items-center justify-center w-full h-full space-y-1 transition-all duration-300 relative ${
           isActive ? 'text-brand-gold' : 'text-gray-400 hover:text-gray-200'
        }`}
      >
        {isActive && (
           <span className="absolute top-0 left-1/2 -translate-x-1/2 w-8 h-0.5 bg-brand-gold shadow-[0_0_10px_#d4af37]"></span>
        )}
        <Icon size={20} strokeWidth={isActive ? 2.5 : 2} />
        <span className="text-[10px] font-medium tracking-wide">{label}</span>
      </button>
    );
  };

  return (
    <div className="fixed bottom-0 inset-x-0 z-50 md:hidden">
      {/* Curved Background Shape */}
      <div className="absolute inset-0 bg-[#0f1115] border-t border-white/10 shadow-[0_-10px_40px_rgba(0,0,0,0.5)]"></div>

      <div className="relative flex justify-between items-end h-[70px] pb-safe px-2 max-w-md mx-auto">

        {/* Left Links */}
        <div className="flex-1 flex justify-around items-center h-full pb-2">
           <NavItem id="home" icon={Home} label="Home" />
           <NavItem id="services" icon={Layers} label="Services" />
        </div>

        {/* CENTER CTA BUTTON (RAISED) */}
        <div className="relative w-20 flex justify-center -top-6">
           <a 
             href="tel:6784287630"
             className="absolute flex items-center justify-center w-16 h-16 bg-gradient-to-br from-brand-gold to-yellow-600 rounded-full shadow-[0_10px_25px_rgba(212,175,55,0.4)] border-4 border-[#0f1115] transform active:scale-95 transition-transform duration-200 group"
             aria-label="Call Now"
           >
              {/* Notification Badge */}
              {showNotification && (
                <span className="absolute top-0 right-0 flex h-4 w-4 z-20">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                  <span className="relative inline-flex rounded-full h-4 w-4 bg-red-600 border border-white text-[9px] text-white items-center justify-center font-bold">1</span>
                </span>
              )}

              {/* Pulse Effect */}
              <div className="absolute inset-0 rounded-full border border-white/30 animate-ping opacity-20"></div>

              <Phone size={28} className="text-white fill-white drop-shadow-md" />
           </a>
           <span className="absolute -bottom-2 text-[10px] font-bold text-brand-gold uppercase tracking-wider opacity-80 pt-1">Call</span>
        </div>

        {/* Right Links */}
        <div className="flex-1 flex justify-around items-center h-full pb-2">
           {/* Using LocalProjects ID but labeling as 'Work' or 'Gallery' */}
           <NavItem id="local-projects" icon={Image} label="Work" />
