import React, { useState, useEffect } from 'react';
import { Home, Layers, Phone, Mail, Image, Camera } from 'lucide-react';

export const MobileNav: React.FC = () => {
  const [activeSection, setActiveSection] = useState('home');

  useEffect(() => {
    const observerOptions = {
      root: null,
      rootMargin: '0px',
      threshold: 0.3
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          setActiveSection(entry.target.id);
        }
      });
    }, observerOptions);

    const sections = ['home', 'services', 'local-projects', 'portfolio', 'contact'];
    sections.forEach(id => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });

    return () => {
      observer.disconnect();
    };
  }, []);

  const scrollTo = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const NavItem = ({ id, icon: Icon, label }: { id: string, icon: any, label?: string }) => {
    const isActive = activeSection === id;
    return (
      <button 
        onClick={() => scrollTo(id)}
        className={`flex flex-col items-center justify-center p-2 transition-all duration-300 relative group ${
           isActive ? 'text-brand-gold' : 'text-gray-400 hover:text-white'
        }`}
      >
        <Icon size={20} strokeWidth={isActive ? 2.5 : 2} />
        {isActive && (
           <span className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-1 h-1 bg-brand-gold rounded-full shadow-[0_0_5px_#d4af37]"></span>
        )}
      </button>
    );
  };

  return (
    // Floating Glass Island Design
    <div className="fixed bottom-6 left-4 right-4 z-50 md:hidden flex justify-center pointer-events-none">
       <div className="bg-[#0f1115]/90 backdrop-blur-xl border border-white/10 rounded-2xl shadow-[0_10px_30px_-5px_rgba(0,0,0,0.5)] px-4 py-2 w-full max-w-sm flex justify-between items-center pointer-events-auto">

          <NavItem id="home" icon={Home} />
          <NavItem id="services" icon={Layers} />

          {/* Center Call Button (Highlighted but integrated) */}
          <div className="relative -top-5">
             <a 
               href="tel:6784287630"
               className="flex items-center justify-center w-14 h-14 bg-gradient-to-br from-brand-gold to-yellow-600 rounded-full shadow-[0_8px_20px_rgba(212,175,55,0.4)] border-4 border-[#0f1115] text-white transform active:scale-95 transition-transform"
             >
                <Phone size={24} fill="currentColor" />
             </a>
          </div>

          <NavItem id="portfolio" icon={Camera} />
          <NavItem id="contact" icon={Mail} />
       </div>
    </div>
  );
};

