                 <Services onModalChange={setIsServiceModalOpen} />
                 <Testimonials />
                 <WhyChooseUs />
              </Suspense>
           </ErrorBoundary>
        </LazyBlock>

        {/* PRIORITY 3: Visual Proof */}
        <LazyBlock minHeight="1200px">
